)

FIELDS = ["a", "b", "c", "d"]
ROWS_PER_EXAMPLE = 6

# ---------------------------------------------------------------- expression generation
_numbers = st.one_of(
    st.integers(0, 1000).map(str),
    st.tuples(st.integers(0, 1000), st.integers(0, 99)).map(lambda t: f"{t[0]}.{t[1]:02d}"),
).map(Num)
_leaves = st.one_of(_numbers, st.sampled_from(FIELDS).map(Field))


def _extend(children):
    return st.one_of(
        children.map(Neg),
        st.tuples(st.sampled_from("+-*/"), children, children).map(lambda t: BinOp(*t)),
    )


expressions = st.recursive(_leaves, _extend, max_leaves=8)

_PREC = {"+": 1, "-": 1, "*": 2, "/": 2}


def render(node: Node, parent_prec: int = 0, right_side: bool = False) -> str:
    """Render with the minimum parentheses the grammar needs (exercises precedence/associativity)."""
    if isinstance(node, Num):
        return node.text
    if isinstance(node, Field):
        return node.name
    if isinstance(node, Neg):
        inner = node.operand
        text = render(inner, 3)
        return "-" + text
    prec = _PREC[node.op]
    text = f"{render(node.left, prec)} {node.op} {render(node.right, prec, True)}"
    if prec < parent_prec or (prec == parent_prec and right_side):
        return f"({text})"
    return text


# ---------------------------------------------------------------- data generation
_good_numbers = st.one_of(
    st.integers(-1000, 1000),
    st.tuples(st.integers(-1000, 1000), st.integers(0, 99)).map(
        lambda t: float(f"{t[0]}.{t[1]:02d}")
    ),
    st.just(0),
