_bad_values = st.sampled_from(["text", "12", "", True, False, None, [1, 2], {"x": 1}])
_field_value = st.one_of(_good_numbers, _good_numbers, _bad_values)
_MISSING = object()
data_objects = st.fixed_dictionaries(
