).map(lambda d: {k: v for k, v in d.items() if v is not _MISSING})


# ---------------------------------------------------------------- Python oracle
def _is_number(value) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def oracle(node: Node, data: dict):
    """Reference evaluator: None on missing/non-numeric field, division by zero or non-finite."""
    result = _eval(node, data)
    if result is None or not math.isfinite(result):
        return None
    return result


def _eval(node: Node, data: dict):
    if isinstance(node, Num):
        return float(node.text)
    if isinstance(node, Field):
        value = data.get(node.name)
        return float(value) if _is_number(value) else None
    if isinstance(node, Neg):
        inner = _eval(node.operand, data)
        return None if inner is None else -inner
    left, right = _eval(node.left, data), _eval(node.right, data)
    if left is None or right is None:
        return None
    if node.op == "+":
        return left + right
    if node.op == "-":
        return left - right
    if node.op == "*":
        return left * right
    return None if right == 0.0 else left / right


def _spark_results(spark, text: str, rows: list[dict]) -> list:
    df = spark.createDataFrame(
        [(i, json.dumps(row)) for i, row in enumerate(rows)], "idx int, data string"
    )
    out = df.select("idx", compile_expression(text, "data").alias("r")).orderBy("idx").collect()
    return [r["r"] for r in out]


def _same(actual, expected) -> bool:
    if expected is None or actual is None:
        return expected is None and actual is None
    return math.isclose(actual, expected, rel_tol=1e-9, abs_tol=1e-9)


# ---------------------------------------------------------------- properties
@settings(
    max_examples=100,
    deadline=None,
    suppress_health_check=[HealthCheck.function_scoped_fixture, HealthCheck.too_slow],
)
@given(ast=expressions, rows=st.lists(data_objects, min_size=ROWS_PER_EXAMPLE, max_size=ROWS_PER_EXAMPLE))
def test_compiled_expression_matches_python_oracle(spark, ast, rows):
    text = render(ast)
    # The rendered text must parse back to the generated tree (precedence and associativity).
    assert parse_expression(text) == ast, text

    actual = _spark_results(spark, text, rows)
    for row, got in zip(rows, actual):
        expected = oracle(ast, row)
        assert _same(got, expected), f"{text!r} on {row!r}: spark={got!r} oracle={expected!r}"


@settings(
    max_examples=100,
    deadline=None,
    suppress_health_check=[HealthCheck.function_scoped_fixture, HealthCheck.too_slow],
)
@given(
    name=st.sampled_from(FIELDS),
    bad=st.one_of(_bad_values, st.just(_MISSING)),
    op=st.sampled_from("+-*/"),
    other=st.integers(1, 100),
    zero=st.sampled_from(["0", "0.0", "0.00"]),
)
def test_failures_give_null(spark, name, bad, op, other, zero):
    """Missing/non-numeric operands and division by zero null out the whole expression."""
    row = {} if bad is _MISSING else {name: bad}
    cases = [
        (f"{name} {op} {other}", row),
        (f"{other} {op} {name}", row),
        (f"{other} / {zero}", {}),
        (f"{other} / ({name} - {name})", {name: other}),
    ]
    for text, data in cases:
        (got,) = _spark_results(spark, text, [data])
        assert got is None, f"{text!r} on {data!r} should be null, got {got!r}"

